class TextScramble{constructor(t){this.el=t,this.chars="!<>-_\\/[]{}\u2014=+*^?#________",this.update=this.update.bind(this)}setText(t){const s=this.el.innerText;console.log(s);const h=Math.max(s.length,t.length),i=new Promise(e=>this.resolve=e);this.queue=[];for(let e=0;e<h;e++){const o=s[e]||"",n=t[e]||"",r=Math.floor(40*Math.random()),a=r+Math.floor(40*Math.random());this.queue.push({from:o,to:n,start:r,end:a})}return cancelAnimationFrame(this.frameRequest),this.frame=0,this.update(),i}update(){let t="",s=0;for(let h=0,i=this.queue.length;h<i;h++){let{from:e,to:o,start:n,end:r,char:a}=this.queue[h];this.frame>=r?(s++,t+=o):this.frame>=n?((!a||Math.random()<.28)&&(a=this.randomChar(),this.queue[h].char=a),t+=`<span class="dud">${a}</span>`):t+=e}this.el.innerHTML=t,s===this.queue.length?this.resolve():(this.frameRequest=requestAnimationFrame(this.update),this.frame++)}randomChar(){return this.chars[Math.floor(Math.random()*this.chars.length)]}}